typedef unsigned int u_int;

#define MAX_LOOSE_PARTICLES 100
#define MAX_TRAIL_GENERATORS 4
#define MAX_LIP_SPLASHES 2
#define MAX_CRASH_NODES 2000

struct nglParticleSystem
{
  char pad0[24];
  float Life;
  float Dura;
  float Rlife;
  float Ctime;
  char pad1[184];
};

struct loose_t
{
  nglParticleSystem part;
};

struct trail
{
  int valid;
  bool is_valid() { return valid; }
  void reset();
};

struct lip_splash_t
{
  char pad[568];
  bool valid;
  char tail[15];
};

struct crashnode_t
{
  char pad[28];
  crashnode_t *Next;
};

struct entity
{
  virtual void v00(); virtual void v01(); virtual void v02(); virtual void v03();
  virtual void v04(); virtual void v05(); virtual void v06(); virtual void v07();
  virtual void v08(); virtual void v09(); virtual void v10(); virtual void v11();
  virtual void v12(); virtual void v13(); virtual void v14(); virtual void v15();
  virtual void v16(); virtual void v17(); virtual void v18(); virtual void v19();
  virtual void v20(); virtual void v21(); virtual void v22(); virtual void v23();
  virtual void v24(); virtual void v25(); virtual void v26(); virtual void v27();
  virtual void v28(); virtual void v29(); virtual void v30(); virtual void v31();
  virtual void v32(); virtual void v33(); virtual void v34(); virtual void v35();
  virtual void v36(); virtual void v37(); virtual void v38(); virtual void v39();
  virtual void v40(); virtual void v41(); virtual void v42(); virtual void v43();
  virtual void set_visible(bool);
};

extern int currentparticle;
extern loose_t LooseParticles[MAX_LOOSE_PARTICLES];
extern trail *g_trails[MAX_TRAIL_GENERATORS];
extern lip_splash_t lip_splashes[MAX_LIP_SPLASHES];
extern crashnode_t crashnodes[MAX_CRASH_NODES];
extern crashnode_t *CrashFreeHead;
extern crashnode_t *CrashHead;
extern entity *tube_spit_entity;

void ks_fx_reset (void)
{
	u_int i,j;

	currentparticle = 0;

	// Reset Loose Particles
	for(i=0;i<MAX_LOOSE_PARTICLES;i++)
	{
		LooseParticles[i].part.Ctime = 1;
		LooseParticles[i].part.Dura = LooseParticles[i].part.Life = LooseParticles[i].part.Rlife = 0;
	}

	// Reset Trail Geometry
	for (j = 0; j < MAX_TRAIL_GENERATORS; j++)
		if (g_trails[j]->is_valid ())
			g_trails[j]->reset ();

	for (i = 0; i < MAX_LIP_SPLASHES; i++)
		lip_splashes[i].valid = false;

	for (u_int i = 0; i < MAX_CRASH_NODES; i++)
		crashnodes[i].Next = &crashnodes[i + 1];
	crashnodes[ MAX_CRASH_NODES - 1 ].Next = 0;

	CrashFreeHead = &crashnodes[0];
	CrashHead=0;

	if (tube_spit_entity)
		tube_spit_entity->set_visible(false);
}
